#!/usr/bin/env python3
from PIL import Image
from PIL.ExifTags import TAGS

# Solution for Challenge 2: Say Cheese!
# Extract EXIF metadata from JPEG images

try:
    image = Image.open('photo.jpg')
    exif_data = image._getexif()

    if exif_data:
        print("\n=== EXIF Data Found ===")
        for tag_id, value in exif_data.items():
            tag_name = TAGS.get(tag_id, tag_id)
            print(f"{tag_name}: {value}")

            # Flag might be in comments or descriptions
            if 'comment' in tag_name.lower() or 'flag' in str(value).lower():
                print(f"\n*** POSSIBLE FLAG: {value} ***")
    else:
        print("No EXIF data found in this image.")

except Exception as e:
    print(f"Error: {e}")
    print("Make sure photo.jpg exists in the current directory.")

#!/usr/bin/env python3
from PIL import Image

# Solution for Challenge 4: Between the Lines
# Extract data hidden using LSB steganography

try:
    image = Image.open('stego.png').convert('RGB')
    pixels = image.load()
    width, height = image.size

    print("Extracting LSB data from image...")

    bits = []
    for y in range(height):
        for x in range(width):
            r, g, b = pixels[x, y]
            # Extract LSB from red channel
            bits.append(str(r & 1))

            # Stop if we have enough bits (estimate: flag is ~25 chars = 200 bits)
            if len(bits) >= 256:
                break
        if len(bits) >= 256:
            break

    # Convert bits to ASCII
    message = ''
    for i in range(0, len(bits), 8):
        byte = ''.join(bits[i:i+8])
        if len(byte) == 8:
            char = chr(int(byte, 2))
            message += char
            if len(message) > 1 and 'flag{' in message:
                # Found it, keep going until we hit }
                continue

    print(f"\nExtracted message: {message}")

    # Extract just the flag
    import re
    flags = re.findall(r'flag\{[^}]+\}', message)
    if flags:
        print(f"\n*** FLAG: {flags[0]} ***")

except Exception as e:
    print(f"Error: {e}")
    print("Make sure stego.png exists in the current directory.")

#!/usr/bin/env python3
import requests
import json

# Challenge 9: Inspect Me - Web Forensics
# Use API requests to extract the flag from server response

# Common API endpoints to try
endpoints = [
    'https://ctf.example.com/api/flag',
    'https://ctf.example.com/api/secret',
    'https://ctf.example.com/api/challenge/9',
    'https://ctf.example.com/api/data',
]

print("Attempting to fetch flag from API endpoints...\n")

for endpoint in endpoints:
    try:
        print(f"Trying: {endpoint}")
        response = requests.get(endpoint, timeout=5)

        if response.status_code == 200:
            print(f"Status: {response.status_code}")

            # Try to parse as JSON
            try:
                data = response.json()
                print(f"Response: {json.dumps(data, indent=2)}\n")

                # Look for flag in response
                if 'flag' in str(data):
                    print("*** FLAG FOUND IN RESPONSE ***")
                    if isinstance(data, dict):
                        for key, value in data.items():
                            if 'flag' in key.lower():
                                print(f"Flag: {value}")
                            if 'flag' in str(value).lower():
                                print(f"Found in {key}: {value}")
            except:
                print(f"Raw response: {response.text}\n")
        else:
            print(f"Status: {response.status_code} (not found)\n")

    except requests.exceptions.RequestException as e:
        print(f"Error: {e}\n")

print("If no flag found, try these alternatives:")
print("1. Check the Network tab in Browser DevTools (F12)")
print("2. Look for WebSocket connections in DevTools")
print("3. Check localStorage/sessionStorage for data")
print("4. Inspect all XHR requests and their responses")
